import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";

/**
 * POST /api/submit-match
 *
 * Server-side validation of match results.
 * The client sends the final board state + match metadata.
 * The server:
 * 1. Verifies the user's auth session
 * 2. Validates parameters
 * 3. Calls the `submit_match_result` RPC (which handles XP/level updates securely)
 * 4. Returns the result
 *
 * The solution is NOT sent to the client from this endpoint.
 * For Solo/Daily, the client already has the solution locally (generated by the engine).
 * For Ranked, the solution is stored in `match_solutions` (inaccessible via RLS).
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const {
      mode,
      difficulty,
      elapsedSec,
      errors,
      hintsUsed,
      completed,
      xpEarned,
      score,
      isRecord,
      boardSeed,
      finalBoard,
    } = body;

    // Get the user's access token from the Authorization header
    const authHeader = request.headers.get("authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
    }

    const token = authHeader.replace("Bearer ", "");

    // Create a Supabase client with the user's token (acts as the user)
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
    const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
    const supabase = createClient(supabaseUrl, supabaseKey, {
      global: { headers: { Authorization: `Bearer ${token}` } },
    });

    // Verify the session is valid
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) {
      return NextResponse.json({ error: "Invalid session" }, { status: 401 });
    }

    // Validate parameters
    if (!["solo", "daily", "duo", "ranked"].includes(mode)) {
      return NextResponse.json({ error: "Invalid mode" }, { status: 400 });
    }
    if (!["easy", "medium", "hard", "expert"].includes(difficulty)) {
      return NextResponse.json({ error: "Invalid difficulty" }, { status: 400 });
    }
    if (typeof elapsedSec !== "number" || elapsedSec < 0 || elapsedSec > 3600) {
      return NextResponse.json({ error: "Invalid time" }, { status: 400 });
    }
    if (typeof errors !== "number" || errors < 0 || errors > 100) {
      return NextResponse.json({ error: "Invalid error count" }, { status: 400 });
    }

    // For completed games, validate the final board (81 chars, digits 0-9)
    if (completed) {
      if (!finalBoard || finalBoard.length !== 81) {
        return NextResponse.json({ error: "Invalid board" }, { status: 400 });
      }
      // Basic format check
      if (!/^[0-9]{81}$/.test(finalBoard)) {
        return NextResponse.json({ error: "Invalid board format" }, { status: 400 });
      }
      // Note: Full solution validation would require the server to have the solution.
      // For Solo/Daily, the solution is generated client-side (same engine).
      // For Ranked, the solution is in match_solutions (validated by RPC).
      // This is a known limitation — the RPC handles the authoritative XP update.
    }

    // Call the RPC function (SECURITY DEFINER) to insert match + update XP
    const { data, error } = await supabase.rpc("submit_match_result", {
      p_mode: mode,
      p_difficulty: difficulty,
      p_elapsed_sec: elapsedSec,
      p_errors: errors,
      p_hints_used: hintsUsed,
      p_completed: completed,
      p_xp_earned: xpEarned,
      p_score: score,
      p_is_record: isRecord,
      p_board_seed: boardSeed || "",
      p_final_board: finalBoard || "",
    });

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json(data);
  } catch (err) {
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
